+  // Send new downwind info for sweep
+  double *buf[3] = {
+    sdom->plane_data[0]->ptr(),
+    sdom->plane_data[1]->ptr(),
+    sdom->plane_data[2]->ptr()
+  };
+  postSends(sdom, buf);
+}
